import { readFile, writeFile, rename, mkdir } from "node:fs/promises";
import { dirname } from "node:path";
import { randomUUID } from "node:crypto";

// A tiny JSON-file-backed book store. Writes are serialized and atomic
// (write to temp file, then rename) so a crash never leaves a half-written file.
export function createStore(filePath) {
  let books = null;
  let queue = Promise.resolve();

  async function load() {
    if (books) return books;
    try {
      const parsed = JSON.parse(await readFile(filePath, "utf8"));
      books = Array.isArray(parsed) ? parsed : [];
    } catch (err) {
      if (err.code !== "ENOENT") throw err;
      books = [];
    }
    return books;
  }

  function persist() {
    const snapshot = JSON.stringify(books, null, 2);
    queue = queue.then(async () => {
      await mkdir(dirname(filePath), { recursive: true });
      const tmp = `${filePath}.${process.pid}.tmp`;
      await writeFile(tmp, snapshot);
      await rename(tmp, filePath);
    });
    return queue;
  }

  return {
    async list() {
      return [...(await load())];
    },
    async get(id) {
      return (await load()).find((b) => b.id === id) ?? null;
    },
    async add({ title, author, notes = "" }) {
      await load();
      const book = {
        id: randomUUID().slice(0, 8),
        title,
        author,
        notes,
        status: "reading",
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await persist();
      return book;
    },
    async finish(id) {
      const book = (await load()).find((b) => b.id === id);
      if (!book) return null;
      if (book.status !== "finished") {
        book.status = "finished";
        book.finishedAt = new Date().toISOString();
        await persist();
      }
      return book;
    },
  };
}

