const MAX_BODY = 64 * 1024;

export function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #222; }
  a { color: #1a5fb4; }
  h1 a { color: inherit; text-decoration: none; }
  ul { padding-left: 1.2rem; }
  li { margin: .4rem 0; }
  li form { display: inline; }
  .muted { color: #666; }
  .notes { white-space: pre-wrap; background: #f6f6f6; padding: .75rem 1rem; border-radius: 6px; }
  label { display: block; margin-top: .6rem; }
  input, textarea { width: 100%; box-sizing: border-box; padding: .4rem; font: inherit; }
  button { margin-top: .6rem; padding: .35rem .8rem; font: inherit; cursor: pointer; }
  li button { margin: 0 0 0 .5rem; padding: .1rem .5rem; font-size: .85rem; }
  .error { color: #a51d2d; }
</style>
</head>
<body>
<h1><a href="/">My books</a></h1>
${body}
</body>
</html>`;
}

function bookLink(book) {
  return `<a href="/books/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a> <span class="muted">by ${escapeHtml(book.author)}</span>`;
}

function homePage(books, { error, values = {} } = {}) {
  const reading = books.filter((b) => b.status !== "finished");
  const finished = books
    .filter((b) => b.status === "finished")
    .sort((a, b) => (b.finishedAt ?? "").localeCompare(a.finishedAt ?? ""));

  const readingList = reading.length
    ? `<ul>${reading
        .map(
          (b) => `<li>${bookLink(b)}
<form method="post" action="/books/${encodeURIComponent(b.id)}/finish"><button type="submit">Mark finished</button></form></li>`
        )
        .join("\n")}</ul>`
    : `<p class="muted">Nothing on the go right now.</p>`;

  const finishedList = finished.length
    ? `<ul>${finished.map((b) => `<li>${bookLink(b)}</li>`).join("\n")}</ul>`
    : `<p class="muted">No finished books yet.</p>`;

  return layout(
    "My books",
    `<h2>Currently reading</h2>
${readingList}
<h2>Finished</h2>
${finishedList}
<h2>Add a book</h2>
${error ? `<p class="error">${escapeHtml(error)}</p>` : ""}
<form method="post" action="/books">
  <label>Title <input name="title" required maxlength="300" value="${escapeHtml(values.title)}"></label>
  <label>Author <input name="author" required maxlength="300" value="${escapeHtml(values.author)}"></label>
  <label>Notes <textarea name="notes" rows="4" maxlength="20000">${escapeHtml(values.notes)}</textarea></label>
  <button type="submit">Add book</button>
</form>`
  );
}

function bookPage(book) {
  const status =
    book.status === "finished"
      ? `Finished${book.finishedAt ? ` on ${escapeHtml(book.finishedAt.slice(0, 10))}` : ""}`
      : `Currently reading`;
  const finishForm =
    book.status === "finished"
      ? ""
      : `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish"><button type="submit">Mark finished</button></form>`;
  return layout(
    `${book.title} by ${book.author}`,
    `<h2>${escapeHtml(book.title)}</h2>
<p>by ${escapeHtml(book.author)}</p>
<p class="muted">${status}</p>
<h3>Notes</h3>
${book.notes ? `<div class="notes">${escapeHtml(book.notes)}</div>` : `<p class="muted">No notes.</p>`}
${finishForm}
<p><a href="/">&larr; All books</a></p>`
  );
}

function send(res, status, html) {
  res.writeHead(status, { "Content-Type": "text/html; charset=utf-8" });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function readForm(req) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on("data", (chunk) => {
      size += chunk.length;
      if (size > MAX_BODY) {
        reject(Object.assign(new Error("Body too large"), { status: 413 }));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on("end", () => resolve(new URLSearchParams(Buffer.concat(chunks).toString("utf8"))));
    req.on("error", reject);
  });
}

const notFound = () => layout("Not found", `<p>That book doesn't exist.</p><p><a href="/">&larr; All books</a></p>`);

export function createApp(store) {
  return async function handler(req, res) {
    try {
      const url = new URL(req.url, "http://localhost");
      const path = url.pathname.replace(/\/+$/, "") || "/";
      let m;

      if (path === "/" && req.method === "GET") {
        return send(res, 200, homePage(await store.list()));
      }

      if (path === "/books" && req.method === "POST") {
        const form = await readForm(req);
        const values = {
          title: (form.get("title") ?? "").trim().slice(0, 300),
          author: (form.get("author") ?? "").trim().slice(0, 300),
          notes: (form.get("notes") ?? "").trim().slice(0, 20000),
        };
        if (!values.title || !values.author) {
          return send(res, 400, homePage(await store.list(), { error: "Title and author are required.", values }));
        }
        const book = await store.add(values);
        return redirect(res, `/books/${encodeURIComponent(book.id)}`);
      }

      if ((m = path.match(/^\/books\/([^/]+)$/)) && req.method === "GET") {
        const book = await store.get(decodeURIComponent(m[1]));
        return book ? send(res, 200, bookPage(book)) : send(res, 404, notFound());
      }

      if ((m = path.match(/^\/books\/([^/]+)\/finish$/)) && req.method === "POST") {
        await readForm(req);
        const book = await store.finish(decodeURIComponent(m[1]));
        if (!book) return send(res, 404, notFound());
        const back = req.headers.referer && new URL(req.headers.referer, "http://localhost").pathname;
        return redirect(res, back && back.startsWith("/books/") ? back : "/");
      }

      return send(res, 404, layout("Not found", `<p>Page not found.</p><p><a href="/">&larr; All books</a></p>`));
    } catch (err) {
      if (err.status === 413) return send(res, 413, layout("Too large", "<p>That submission is too large.</p>"));
      console.error(err);
      return send(res, 500, layout("Error", "<p>Something went wrong.</p>"));
    }
  };
}

