    book.status === "finished"
      ? `Finished${book.finishedAt ? ` on ${escapeHtml(book.finishedAt.slice(0, 10))}` : ""}`
      : `Currently reading`;
  const finishForm =
    book.status === "finished"
      ? ""
      : `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish"><button type="submit">Mark finished</button></form>`;
  return layout(
    `${book.title} by ${book.author}`,
    `<h2>${escapeHtml(book.title)}</h2>
<p>by ${escapeHtml(book.author)}</p>
<p class="muted">${status}</p>
<h3>Notes</h3>
${book.notes ? `<div class="notes">${escapeHtml(book.notes)}</div>` : `<p class="muted">No notes.</p>`}
${finishForm}
<p><a href="/">&larr; All books</a></p>`
  );
}

function send(res, status, html) {
  res.writeHead(status, { "Content-Type": "text/html; charset=utf-8" });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function readForm(req) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on("data", (chunk) => {
      size += chunk.length;
      if (size > MAX_BODY) {
        reject(Object.assign(new Error("Body too large"), { status: 413 }));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on("end", () => resolve(new URLSearchParams(Buffer.concat(chunks).toString("utf8"))));
    req.on("error", reject);
  });
}

const notFound = () => layout("Not found", `<p>That book doesn't exist.</p><p><a href="/">&larr; All books</a></p>`);

export function createApp(store) {
  return async function handler(req, res) {
    try {
      const url = new URL(req.url, "http://localhost");
      const path = url.pathname.replace(/\/+$/, "") || "/";
      let m;

      if (path === "/" && req.method === "GET") {
        return send(res, 200, homePage(await store.list()));
      }

      if (path === "/books" && req.method === "POST") {
        const form = await readForm(req);
        const values = {
          title: (form.get("title") ?? "").trim().slice(0, 300),
          author: (form.get("author") ?? "").trim().slice(0, 300),
          notes: (form.get("notes") ?? "").trim().slice(0, 20000),
        };
        if (!values.title || !values.author) {
          return send(res, 400, homePage(await store.list(), { error: "Title and author are required.", values }));
        }
        const book = await store.add(values);
        return redirect(res, `/books/${encodeURIComponent(book.id)}`);
      }

      if ((m = path.match(/^\/books\/([^/]+)$/)) && req.method === "GET") {
        const book = await store.get(decodeURIComponent(m[1]));
        return book ? send(res, 200, bookPage(book)) : send(res, 404, notFound());
      }

      if ((m = path.match(/^\/books\/([^/]+)\/finish$/)) && req.method === "POST") {
        await readForm(req);
        const book = await store.finish(decodeURIComponent(m[1]));
        if (!book) return send(res, 404, notFound());
        const back = req.headers.referer && new URL(req.headers.referer, "http://localhost").pathname;
        return redirect(res, back && back.startsWith("/books/") ? back : "/");
      }

      return send(res, 404, layout("Not found", `<p>Page not found.</p><p><a href="/">&larr; All books</a></p>`));
    } catch (err) {
      if (err.status === 413) return send(res, 413, layout("Too large", "<p>That submission is too large.</p>"));
      console.error(err);
      return send(res, 500, layout("Error", "<p>Something went wrong.</p>"));
    }
  };
}

import { createServer } from "node:http";
import { resolve } from "node:path";
import { createStore } from "./src/store.js";
import { createApp } from "./src/app.js";

const port = Number(process.env.PORT) || 3000;
const dataFile = resolve(process.env.BOOKS_FILE || "data/books.json");

const server = createServer(createApp(createStore(dataFile)));
server.listen(port, () => {
  console.log(`Books app running at http://localhost:${port} (data: ${dataFile})`);
});

