import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { createServer } from "node:http";
import { mkdtemp, rm, readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createStore } from "../src/store.js";
import { createApp } from "../src/app.js";

let dir, file, server, base;

async function start() {
  server = createServer(createApp(createStore(file)));
  await new Promise((r) => server.listen(0, r));
  base = `http://localhost:${server.address().port}`;
}
async function stop() {
  await new Promise((r) => server.close(r));
}
const post = (path, data, headers = {}) =>
  fetch(base + path, {
    method: "POST",
    body: new URLSearchParams(data),
    redirect: "manual",
    headers,
  });

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), "books-"));
  file = join(dir, "books.json");
  await start();
});
afterEach(async () => {
  await stop();
  await rm(dir, { recursive: true, force: true });
});

describe("books app", () => {
  it("shows empty lists and the add form", async () => {
    const html = await (await fetch(base + "/")).text();
    expect(html).toContain("Currently reading");
    expect(html).toContain("Finished");
    expect(html).toContain('action="/books"');
  });

  it("adds a book, links to it, and shows details", async () => {
    const res = await post("/books", { title: "Dune", author: "Frank Herbert", notes: "Spice." });
    expect(res.status).toBe(303);
    const location = res.headers.get("location");
    expect(location).toMatch(/^\/books\/[\w-]+$/);

    const detail = await (await fetch(base + location)).text();
    expect(detail).toContain("Dune");
    expect(detail).toContain("Frank Herbert");
    expect(detail).toContain("Spice.");

    const home = await (await fetch(base + "/")).text();
    expect(home).toContain(`href="${location}"`);
  });

  it("rejects a book without title or author", async () => {
    const res = await post("/books", { title: "", author: "Someone" });
    expect(res.status).toBe(400);
    expect(await res.text()).toContain("Title and author are required");
  });

  it("marks a book as finished", async () => {
    const loc = (await post("/books", { title: "Emma", author: "Jane Austen" })).headers.get("location");
    const res = await post(`${loc}/finish`, {}, { referer: base + "/" });
    expect(res.status).toBe(303);
    expect(res.headers.get("location")).toBe("/");

    const home = await (await fetch(base + "/")).text();
    const finishedSection = home.split("<h2>Finished</h2>")[1].split("<h2>Add a book</h2>")[0];
    expect(finishedSection).toContain("Emma");
    const readingSection = home.split("<h2>Finished</h2>")[0];
    expect(readingSection).not.toContain("Emma");
  });

  it("escapes user content", async () => {
    const loc = (await post("/books", { title: "<script>x</script>", author: "A", notes: "<b>hi</b>" })).headers.get("location");
    const html = await (await fetch(base + loc)).text();
    expect(html).not.toContain("<script>x</script>");
    expect(html).toContain("&lt;script&gt;");
  });

  it("returns 404 for unknown books", async () => {
    expect((await fetch(base + "/books/nope")).status).toBe(404);
    expect((await post("/books/nope/finish", {})).status).toBe(404);
  });

  it("persists books to the JSON file across restarts", async () => {
    const loc = (await post("/books", { title: "Persist", author: "Me" })).headers.get("location");
    await post(`${loc}/finish`, {});
    const saved = JSON.parse(await readFile(file, "utf8"));
    expect(saved).toHaveLength(1);
    expect(saved[0]).toMatchObject({ title: "Persist", status: "finished" });

    await stop();
    await start();
    const detail = await (await fetch(base + loc)).text();
    expect(detail).toContain("Persist");
    expect(detail).toContain("Finished");
  });
});

